    code: ['// java -cp app.jar com.example.Main', 'var c = Class.forName("com.example.Main");', ['c.getClassLoader();           // 앱 로더', 'c.getClassLoader();           // app loader'], 'String.class.getClassLoader() // null', ['// 로딩 → 링크 → 초기화(<clinit>)', '// load → link → initialize (<clinit>)']],
    hl: [[2, 2, 'accent'], [1, 1, 'warn'], [4, 1, 'ok'], [0, 1]],
