      TR.forEach(([a, b, c, x, w], i) => { box2(S, 'tr' + i, x, 4.2, w, .9, a, c, 2); T(S, 'td' + i, x, 5.2, b, 'cz-tc jvx-tiny', 2, { w }); if (i) arw(S, 'ta' + i, [x - .5, 4.65], [x - .05, 4.65], 2); });
