      [['HashMap (cache)', 1.2, 'danger'], ['byte[]', .3, 'warn'], ['String', .15, 'ink-3']].forEach(([n, v, c], i) => { const y = 4.2 + i * .75; T(S, 'hn' + i, 19.0, y, n, 'cz-mono jvx-tiny', 2, { w: 4.0 }); hbar(S, 'hb' + i, 23.6, y + .05, v * 5.0, c, 2); T(S, 'hv' + i, 23.8 + v * 5.0, y, v + ' GB', 'cz-mono jvx-tiny', 2, { w: 1.8 }); });
      lbl(S, 'l2', 19.0, 6.6, ['힙 덤프의 지배자 트리: 무엇이 메모리를 붙잡고 있는지 (누수 찾기)', 'the heap dump’s dominator tree shows what holds memory, revealing leaks'], 'w', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 8.0, ['JFR: 약 1% 부하로 CPU 샘플, 할당, GC, 락 이벤트를 상시 기록 → Mission Control로 분석', 'JFR records CPU, allocation, GC and lock events at ~1% overhead'], 'g', 3, { w: 12.4 });
